commit.message:
fix(mcp): preserve OAuth resource binding when metadata is unavailable (#24589)

## Background

When protected-resource metadata was unavailable, MCP OAuth omitted
resource from authorization, code exchange, and refresh requests.

This allowed authorization servers to apply an unrelated default
resource, creating the audience-binding gap that the OAuth grant wasn’t
explicitly restricted to the MCP API the app intended to access.

## Summary

- Fall back to the canonical MCP URL when metadata is unavailable or
custom resource validation returns undefined.
- Preserve explicit custom resource selection and validation errors

## End-to-End Verification

verified by running the example

<details>

```ts
// Run from examples/ai-functions:
// pnpm exec tsx src/tools/mcp-oauth-resource-binding.ts
// Uses the workspace build of @ai-sdk/mcp and synthetic OAuth responses only.
// No network requests, real authorization codes, or real tokens are used.
import {
  auth,
  type OAuthClientInformation,
  type OAuthClientProvider,
} from '@ai-sdk/mcp';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';

const serverUrl = 'https://mcp.example.com/mcp';
const origin = new URL(serverUrl).origin;
const redirectUrl = 'https://app.example.com/callback';

async function observeResourceBinding(hasResourceMetadata: boolean) {
  let clientInformation: OAuthClientInformation | undefined;
  let verifier: string | undefined;
  let storedState: string | undefined;
  const captured: {
    authorizationUrl?: URL;
    tokenParams?: URLSearchParams;
  } = {};
  const clientMetadata = {
    redirect_uris: [redirectUrl],
    token_endpoint_auth_method: 'none',
    grant_types: ['authorization_code'],
    response_types: ['code'],
  };

  const provider: OAuthClientProvider = {
    redirectUrl,
    clientMetadata,
    tokens: () => undefined,
    saveTokens: () => {},
    clientInformation: () => clientInformation,
    saveClientInformation: value => {
      clientInformation = value;
    },
    saveCodeVerifier: value => {
      verifier = value;
    },
    codeVerifier: () => {
      assert.ok(verifier);
      return verifier;
    },
    state: () => randomUUID(),
    saveState: value => {
      storedState = value;
    },
    storedState: () => storedState,
    redirectToAuthorization: url => {
      captured.authorizationUrl = url;
