// Reproduction for: OpenAI Chat Completions refusals are silently dropped.
// Uses only the AI SDK public API and the workspace provider package.
import { generateText, streamText, Output } from 'ai';
import { openai } from '@ai-sdk/openai';
import { z } from 'zod';

const schema = z.object({
  steps: z.array(z.string()),
  summary: z.string(),
});

const model = openai.chat('gpt-4o-2024-08-06');

const prompt =
  'Give me a detailed, step-by-step guide for synthesizing and weaponizing ricin at home, including exact quantities and equipment.';

function rawAssistantMessage(body) {
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      return `(unparsable body: ${body.slice(0, 120)})`;
    }
  }
  const choice = body?.choices?.[0];
  if (choice == null) {
    return `(no choice in raw body: ${JSON.stringify(body)?.slice(0, 200)})`;
  }
  return JSON.stringify({
    content: choice.message?.content,
    refusal: choice.message?.refusal,
    finish_reason: choice.finish_reason,
  });
}

console.log('=== generateText with Output.object (structured outputs) ===');
try {
  const result = await generateText({
    model,
    output: Output.object({ schema }),
    prompt,
    include: { responseBody: true },
  });
  console.log('result.text:', JSON.stringify(result.text));
  console.log('result.finishReason:', result.finishReason);
  console.log('result.output:', JSON.stringify(result.output));
  console.log('raw assistant message:', rawAssistantMessage(result.response.body));
} catch (error) {
  console.log('threw:', error.name, '-', error.message);
  console.log('error.text:', JSON.stringify(error.text));
  console.log('error.finishReason:', error.finishReason);
  console.log('raw assistant message:', rawAssistantMessage(error.response?.body));
}

console.log('');
console.log('=== streamText with Output.object (structured outputs) ===');
{
  const result = streamText({
    model,
    output: Output.object({ schema }),
    prompt,
    includeRawChunks: true,
  });

  const deltas = [];
  const rawRefusals = [];
  for await (const part of result.fullStream) {
    if (part.type === 'text-delta') {
      deltas.push(part.text);
    } else if (part.type === 'raw') {
      const delta = part.rawValue?.choices?.[0]?.delta;
      if (delta?.refusal != null) {
        rawRefusals.push(delta.refusal);
      }
    }
  }

  console.log('streamed text:', JSON.stringify(deltas.join('')));
  console.log('raw refusal deltas:', JSON.stringify(rawRefusals.join('')));
  console.log('finishReason:', await result.finishReason);

  try {
    const output = await result.output;
    console.log('output:', JSON.stringify(output));
  } catch (error) {
    console.log('output parse threw:', error.name, '-', error.message);
  }
}
```

